<script setup>import {watchEffect,onMounted} from 'vue';import {useRoute} from 'vue-router';import {useProductStore} from '../stores/productStore';import ProductGrid from '../components/product/ProductGrid.vue';const route=useRoute(),s=useProductStore();onMounted(()=>s.init());watchEffect(()=>s.query=String(route.query.q||''))</script><template><main class="page"><div class="page-title"><span class="kicker">SEARCH</span><h1>Kết quả tìm kiếm</h1><input class="search-page-input" v-model="s.query" placeholder="Nhập tên, loại hoặc thương hiệu..."/></div><ProductGrid :products="s.filtered"/></main></template>
